-- Hyprland Lua config (generated by dotman)
-- Refer to: https://wiki.hypr.land/Configuring/Start/

local mainMod = "SUPER"

local terminal    = "ghostty"
local fileManager = "nautilus"
local browser     = "zen-browser"

require("modules.monitors")
require("modules.env")
require("modules.input")
require("modules.look_and_feel")
require("modules.layouts")
require("modules.animations")
require("modules.misc")
require("modules.window_rules")
require("modules.autostart")

hl.bind(mainMod .. " + Return", hl.dsp.exec_cmd(terminal))
hl.bind(mainMod .. " + B", hl.dsp.exec_cmd(browser))
hl.bind(mainMod .. " + F", hl.dsp.exec_cmd(fileManager))
hl.bind(mainMod .. " + Y", hl.dsp.exec_cmd(terminal .. " -e yazi"))
hl.bind(mainMod .. " + P", hl.dsp.exec_cmd(terminal .. " -e btop"))
hl.bind(mainMod .. " + SPACE", hl.dsp.exec_cmd("~/.local/bin/lib/footspawn ~/.local/bin/menu/launcher"))
hl.bind(mainMod .. " + escape", hl.dsp.exec_cmd("~/.local/bin/lib/screensaver-launcher &"))

hl.bind(mainMod .. " + SHIFT + B", hl.dsp.exec_cmd("~/.local/bin/lib/footspawn bluetui"))
hl.bind(mainMod .. " + SHIFT + W", hl.dsp.exec_cmd("~/.local/bin/lib/footspawn impala"))
hl.bind(mainMod .. " + SHIFT + V", hl.dsp.exec_cmd("~/.local/bin/lib/footspawn wiremix"))
hl.bind(mainMod .. " + SHIFT + C", hl.dsp.exec_cmd("~/.local/bin/lib/footspawn btop"))

hl.bind(mainMod .. " + W", hl.dsp.window.close())
hl.bind(mainMod .. " + V", hl.dsp.window.float({ action = "toggle" }))
hl.bind(mainMod .. " + T", hl.dsp.window.fullscreen())
hl.bind(mainMod .. " + P", hl.dsp.window.pseudo())
hl.bind(mainMod .. " + J", hl.dsp.layout("togglesplit"))

hl.bind(mainMod .. " + left",  hl.dsp.focus({ direction = "l" }))
hl.bind(mainMod .. " + right", hl.dsp.focus({ direction = "r" }))
hl.bind(mainMod .. " + up",    hl.dsp.focus({ direction = "u" }))
hl.bind(mainMod .. " + down",  hl.dsp.focus({ direction = "d" }))

hl.bind(mainMod .. " + SHIFT + left",  hl.dsp.window.move({ direction = "l" }))
hl.bind(mainMod .. " + SHIFT + right", hl.dsp.window.move({ direction = "r" }))
hl.bind(mainMod .. " + SHIFT + up",    hl.dsp.window.move({ direction = "u" }))
hl.bind(mainMod .. " + SHIFT + down",  hl.dsp.window.move({ direction = "d" }))

for i = 1, 10 do
    local key = i % 10
    hl.bind(mainMod .. " + " .. key,         hl.dsp.focus({ workspace = i }))
    hl.bind(mainMod .. " + SHIFT + " .. key, hl.dsp.window.move({ workspace = i }))
end

hl.bind(mainMod .. " + mouse_down", hl.dsp.focus({ workspace = "e+1" }))
hl.bind(mainMod .. " + mouse_up",   hl.dsp.focus({ workspace = "e-1" }))

hl.bind(mainMod .. " + mouse:272", hl.dsp.window.drag(),   { mouse = true })
hl.bind(mainMod .. " + mouse:273", hl.dsp.window.resize(), { mouse = true })

hl.bind(mainMod .. " + SHIFT + M", hl.dsp.exit())
hl.bind(mainMod .. " + Backspace", hl.dsp.exec_cmd("~/.config/tofi/scripts/power.sh"))
